"""Independent hand-written contract fixtures; run python -m unittest discover -s scripts -p 'test_*.py'."""
import csv
import hashlib
import io
import json
import tempfile
import unittest
from pathlib import Path

from wdi_pipeline import BASELINE, LEGACY_SHA, ROOT, annual_changes, assert_compatible_join, baseline_digest, build, validate_rows


def row(**updates):
    # Hand-written, not generated by the ETL; a zero poverty observation is valid.
    fixture = {'country_code': 'TJK', 'indicator_code': 'SI.POV.DDAY', 'year': '2023', 'value': '0', 'vintage': 'independent-fixture', 'unit': '% of population', 'ppp_basis': '2021 PPP'}
    return {**fixture, **updates}


class DataContractTests(unittest.TestCase):
    def test_zero_is_preserved(self):
        self.assertEqual(len(validate_rows([row()], require_sets=False)), 1)

    def test_duplicate_key_rejected(self):
        with self.assertRaisesRegex(ValueError, 'Duplicate'):
            validate_rows([row(), row()], require_sets=False)

    def test_different_vintages_not_duplicate(self):
        self.assertEqual(len(validate_rows([row(), row(vintage='second')], require_sets=False)), 2)

    def test_nonfinite_rejected(self):
        for value in ('nan', 'inf', '-inf'):
            with self.assertRaises(ValueError):
                validate_rows([row(value=value)], require_sets=False)

    def test_percentage_outside_domain_rejected(self):
        for value in ('-0.1', '100.1'):
            with self.assertRaises(ValueError):
                validate_rows([row(value=value)], require_sets=False)

    def test_unknown_country_rejected(self):
        with self.assertRaises(ValueError):
            validate_rows([row(country_code='XXX')], require_sets=False)

    def test_unknown_indicator_rejected(self):
        with self.assertRaises(ValueError):
            validate_rows([row(indicator_code='FAKE')], require_sets=False)

    def test_units_required(self):
        with self.assertRaisesRegex(ValueError, 'unit'):
            validate_rows([row(unit='persons')], require_sets=False)

    def test_current_poverty_cannot_use_old_ppp(self):
        with self.assertRaisesRegex(ValueError, 'poverty'):
            validate_rows([row(ppp_basis='2017 PPP')], require_sets=False)

    def test_full_country_indicator_contract_required(self):
        with self.assertRaisesRegex(ValueError, 'six countries'):
            validate_rows([row()])

    def test_missing_vintage_rejected(self):
        with self.assertRaisesRegex(ValueError, 'vintage'):
            validate_rows([row(vintage='')], require_sets=False)

    def test_missing_is_not_zero(self):
        with self.assertRaises(ValueError):
            validate_rows([row(value='')], require_sets=False)

    def test_wrong_year_join_rejected(self):
        with self.assertRaisesRegex(ValueError, 'join'):
            assert_compatible_join([row(year='2023'), row(year='2024')])

    def test_cross_vintage_join_rejected(self):
        with self.assertRaisesRegex(ValueError, 'join'):
            assert_compatible_join([row(), row(vintage='other')])

    def test_same_year_and_vintage_join_valid(self):
        assert_compatible_join([row(), row(indicator_code='SI.POV.LMIC')])

    def test_candidate_public_copy_byte_equal(self):
        release = ROOT / 'data/releases/wdi-2026-10-11-candidate'
        public = ROOT / 'client/public/data/releases/wdi-2026-10-11-candidate'
        for filename in ('observations.csv', 'manifest.json'):
            self.assertEqual((release / filename).read_bytes(), (public / filename).read_bytes())

    def test_coverage_freshness_and_missingness_diagnostics(self):
        quality = json.loads((ROOT / 'data/releases/wdi-2026-10-11-candidate/quality.json').read_text())
        self.assertEqual(len(quality['coverage']), 102)
        renewable = next(r for r in quality['coverage'] if r['country'] == 'TJK' and r['indicator'] == 'EG.FEC.RNEW.ZS')
        self.assertEqual(renewable['latest_year'], 2021)
        self.assertTrue(renewable['stale_before_2023'])
        self.assertEqual(renewable['missing_years'][-1], 2025)

    def test_survey_gap_not_annual_change(self):
        self.assertEqual(annual_changes(row(year='2021', value='10'), row(year='2023', value='20')), ('', ''))

    def test_year_on_year_recomputed(self):
        self.assertEqual(annual_changes(row(year='2022', value='10'), row(year='2023', value='12')), ('2', '20'))

    def test_zero_denominator_not_infinity(self):
        self.assertEqual(annual_changes(row(year='2022', value='0'), row(year='2023', value='2')), ('2', ''))

    def test_negative_growth_and_migration_valid(self):
        validate_rows([row(indicator_code='NY.GDP.MKTP.KD.ZG', value='-7', unit='% annual change'), row(indicator_code='SM.POP.NETM', value='-300', unit='persons')], require_sets=False)

    def test_gross_enrollment_can_exceed_100(self):
        validate_rows([row(indicator_code='SE.SEC.ENRR', value='110', unit='% gross enrollment')], require_sets=False)

    def test_csv_unicode_quotes_commas_newlines(self):
        values = ['Тоҷикистон', 'a,b', 'a"b', 'line\nnext', '0']
        output = io.StringIO(newline='')
        csv.writer(output).writerow(values)
        self.assertEqual(next(csv.reader(io.StringIO(output.getvalue()))), values)

    def test_legacy_snapshot_byte_integrity(self):
        self.assertEqual(baseline_digest(), LEGACY_SHA)

    def test_candidate_reconciles_to_raw_and_is_deterministic(self):
        release = ROOT / 'data/releases/wdi-2026-10-11-candidate'
        self.assertTrue((release / 'manifest.json').exists(), 'Versioned API evidence must be checked in')
        build(release)
        first = (release / 'observations.csv').read_bytes()
        build(release)
        self.assertEqual(first, (release / 'observations.csv').read_bytes())
        manifest = json.loads((release / 'manifest.json').read_text())
        source = {}
        for code in manifest['scope']['indicators']:
            payload = json.loads((release / f'raw/{code}.observations.json').read_text())
            for point in payload[1]:
                if point['value'] is not None:
                    source[(point['countryiso3code'], code, int(point['date']))] = point['value']
        actual = list(csv.DictReader(io.StringIO(first.decode('utf-8'))))
        self.assertEqual(len(source), len(actual))
        for point in actual:
            self.assertEqual(float(point['value']), source[(point['country_code'], point['indicator_code'], int(point['year']))])


if __name__ == '__main__':
    unittest.main()
